<?php
class TicketService
{
    private $pdo;
    public function __construct($pdo){$this->pdo=$pdo;}
    private function id($v){if(!is_int($v)&&!is_string($v))throw new InvalidArgumentException('编号无效。');$s=(string)$v;if(!preg_match('/^[1-9][0-9]*$/D',$s)||strlen($s)>strlen((string)PHP_INT_MAX)||(strlen($s)===strlen((string)PHP_INT_MAX)&&strcmp($s,(string)PHP_INT_MAX)>0))throw new InvalidArgumentException('编号无效。');return (int)$s;}
    private function text($v,$max,$label){if(!is_string($v))throw new InvalidArgumentException($label.'格式无效。');$v=trim($v);if($v===''||mb_strlen($v,'UTF-8')>$max)throw new InvalidArgumentException($label.'不能为空且不超过'.$max.'字。');return $v;}
    private function key($v){if(!is_string($v)||!preg_match('/^[A-Za-z0-9_-]{16,100}$/D',$v))throw new InvalidArgumentException('请求令牌无效，请刷新后重试。');return $v;}
    private function begin(){if($this->pdo->inTransaction())throw new LogicException('工单操作不能嵌套事务。');$this->pdo->beginTransaction();}
    private function operation($actorType,$actorId,$op,$key,$hash){$s=$this->pdo->prepare('SELECT * FROM ticket_operations WHERE actor_type=? AND actor_id=? AND operation=? AND request_key=? FOR UPDATE');$s->execute(array($actorType,$actorId,$op,$key));$r=$s->fetch(PDO::FETCH_ASSOC);if(!$r)return null;if(!hash_equals((string)$r['request_hash'],$hash))throw new RuntimeException('请求令牌已用于其他内容。');return $r;}
    private function saveOperation($ticketId,$actorType,$actorId,$op,$key,$hash,$result){$this->pdo->prepare('INSERT INTO ticket_operations(ticket_id,actor_type,actor_id,operation,request_key,request_hash,result_json,created_at) VALUES(?,?,?,?,?,?,?,?)')->execute(array($ticketId,$actorType,$actorId,$op,$key,$hash,json_encode($result,JSON_UNESCAPED_UNICODE),date('Y-m-d H:i:s')));}
    private function notify($userId,$type,$title,$content,$orderNo=null,$ticketId=null,$eventKey=null){$svc=new NotificationService($this->pdo);$svc->create($userId,$type,$title,$content,$orderNo,'ticket',$ticketId,$eventKey?:('ticket:'.$ticketId.':'.$type));}
    private function ticket($id,$forUpdate=false){$q='SELECT t.* FROM support_tickets t WHERE t.id=?'.($forUpdate?' FOR UPDATE':'');$s=$this->pdo->prepare($q);$s->execute(array($id));$r=$s->fetch(PDO::FETCH_ASSOC);if(!$r)throw new RuntimeException('工单不存在。');$r['order_no']=null;$r['product_name_snapshot']=null;$r['total_amount_cents']=null;if($r['order_id']!==null){$o=$this->pdo->prepare('SELECT order_no,product_name_snapshot,total_amount_cents FROM orders WHERE id=? AND user_id=?');$o->execute(array($r['order_id'],$r['user_id']));$or=$o->fetch(PDO::FETCH_ASSOC);if($or)$r=array_merge($r,$or);}return $r;}
    public function create($uid,$subject,$body,$orderId=null,$key=''){$uid=$this->id($uid);$subject=$this->text($subject,200,'主题');$body=$this->text($body,5000,'内容');$key=$this->key($key);if($orderId===null||$orderId==='')$orderId=null;else $orderId=$this->id($orderId);$hash=hash('sha256',json_encode(array($subject,$body,$orderId),JSON_UNESCAPED_UNICODE));$this->begin();try{$s=$this->pdo->prepare('SELECT id FROM users WHERE id=? AND status="active" FOR UPDATE');$s->execute(array($uid));if(!$s->fetch())throw new RuntimeException('用户不存在或已停用。');$old=$this->operation('user',$uid,'create',$key,$hash);if($old){$result=json_decode($old['result_json'],true);$this->pdo->commit();return $result;}$since=date('Y-m-d H:i:s',time()-3600);$s=$this->pdo->prepare('SELECT COUNT(*) FROM support_tickets WHERE user_id=? AND created_at>=?');$s->execute(array($uid,$since));if((int)$s->fetchColumn()>=5)throw new RuntimeException('提交过于频繁，请稍后再试。');$s=$this->pdo->prepare('SELECT COUNT(*) FROM support_tickets WHERE user_id=? AND status<>"closed"');$s->execute(array($uid));if((int)$s->fetchColumn()>=10)throw new RuntimeException('未关闭工单已达上限。');if($orderId!==null&&$orderId!==''){$orderId=$this->id($orderId);$s=$this->pdo->prepare('SELECT id,order_no FROM orders WHERE id=? AND user_id=?');$s->execute(array($orderId,$uid));$order=$s->fetch(PDO::FETCH_ASSOC);if(!$order)throw new RuntimeException('订单不存在或无权关联。');}else{$orderId=null;$order=null;}$no='TK'.date('ymdHis').strtoupper(bin2hex(random_bytes(3)));$now=date('Y-m-d H:i:s');$this->pdo->prepare('INSERT INTO support_tickets(ticket_no,user_id,order_id,subject,status,version_no,created_at,updated_at) VALUES(?,?,?,? ,"open",1,?,?)')->execute(array($no,$uid,$orderId,$subject,$now,$now));$id=(int)$this->pdo->lastInsertId();$this->pdo->prepare('INSERT INTO ticket_messages(ticket_id,sender_type,sender_user_id,body,created_at) VALUES(?,"user",?,?,?)')->execute(array($id,$uid,$body,$now));$result=array('id'=>$id,'ticket_no'=>$no);$this->saveOperation($id,'user',$uid,'create',$key,$hash,$result);$this->pdo->commit();return $result;}catch(Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}}
    public function listing($uid=null,$filters=array(),$page=1,$perPage=20){$where=array('1=1');$args=array();if($uid!==null){$where[]='t.user_id=?';$args[]=$this->id($uid);}if(isset($filters['status'])&&in_array($filters['status'],array('open','waiting_customer','closed'),true)){$where[]='t.status=?';$args[]=$filters['status'];}$page=max(1,(int)$page);$perPage=max(1,min(50,(int)$perPage));$s=$this->pdo->prepare('SELECT COUNT(*) FROM support_tickets t WHERE '.implode(' AND ',$where));$s->execute($args);$total=(int)$s->fetchColumn();$pages=max(1,(int)ceil($total/$perPage));$page=min($page,$pages);$s=$this->pdo->prepare('SELECT t.*,o.order_no FROM support_tickets t LEFT JOIN orders o ON o.id=t.order_id AND o.user_id=t.user_id WHERE '.implode(' AND ',$where).' ORDER BY t.updated_at DESC,t.id DESC LIMIT '.$perPage.' OFFSET '.(($page-1)*$perPage));$s->execute($args);return array('items'=>$s->fetchAll(PDO::FETCH_ASSOC),'total'=>$total,'page'=>$page,'pages'=>$pages,'per_page'=>$perPage);}
    public function detail($id,$uid=null,$page=1,$perPage=20){$id=$this->id($id);$r=$this->ticket($id);if($uid!==null&&(int)$r['user_id']!==$this->id($uid))throw new RuntimeException('工单不存在。');$page=max(1,(int)$page);$perPage=max(1,min(50,(int)$perPage));$s=$this->pdo->prepare('SELECT COUNT(*) FROM ticket_messages WHERE ticket_id=?');$s->execute(array($id));$total=(int)$s->fetchColumn();$pages=max(1,(int)ceil($total/$perPage));$page=min($page,$pages);$s=$this->pdo->prepare('SELECT * FROM ticket_messages WHERE ticket_id=? ORDER BY id ASC LIMIT '.$perPage.' OFFSET '.(($page-1)*$perPage));$s->execute(array($id));$r['messages']=$s->fetchAll(PDO::FETCH_ASSOC);$r['message_page']=$page;$r['message_pages']=$pages;$r['message_total']=$total;return $r;}
    private function change($id,$actor,$isAdmin,$body,$key,$close,$expectedVersion=null){$id=$this->id($id);if($expectedVersion!==null&&!is_int($expectedVersion)&&!is_string($expectedVersion))throw new InvalidArgumentException('版本号无效。');if($expectedVersion!==null&&!is_int($expectedVersion)&&!ctype_digit($expectedVersion))throw new InvalidArgumentException('版本号无效。');$body=$body===null?null:$this->text($body,5000,'回复内容');$key=$this->key($key);$this->begin();try{$uid=$isAdmin?null:$this->id($actor);$aid=$isAdmin?$this->id($actor):null;if($isAdmin){$s=$this->pdo->prepare('SELECT id FROM admin_users WHERE id=? AND status="active" FOR UPDATE');$s->execute(array($aid));if(!$s->fetch())throw new RuntimeException('管理员身份无效。');}if(!$isAdmin){$s=$this->pdo->prepare('SELECT id FROM users WHERE id=? AND status="active" FOR UPDATE');$s->execute(array($uid));if(!$s->fetch())throw new RuntimeException('用户不存在或已停用。');}$t=$this->ticket($id,true);if(!$isAdmin&&(int)$t['user_id']!==$uid)throw new RuntimeException('工单不存在。');$version=$expectedVersion===null?null:(int)$expectedVersion;$hash=hash('sha256',json_encode(array('ticket_id'=>$id,'body'=>$body,'close'=>$close,'version'=>$version),JSON_UNESCAPED_UNICODE));$op=$this->operation($isAdmin?'admin':'user',$isAdmin?$aid:$uid,$close?'close':'reply',$key,$hash);if($version!==null&&$op===null&&(int)$version!==(int)$t['version_no'])throw new RuntimeException('工单版本已变化，请刷新后重试。');if($op){$result=json_decode($op['result_json'],true);$this->pdo->commit();return $result;}if($t['status']==='closed'){if($close){$result=array('id'=>$id,'status'=>'closed');$this->saveOperation($id,$isAdmin?'admin':'user',$isAdmin?$aid:$uid,'close',$key,$hash,$result);$this->pdo->commit();return $result;}throw new RuntimeException('工单已关闭，不能继续回复。');}if(!$isAdmin){$s=$this->pdo->prepare('SELECT COUNT(*) FROM ticket_messages m JOIN support_tickets t ON t.id=m.ticket_id WHERE t.user_id=? AND m.sender_type="user" AND m.created_at>=?');$s->execute(array($uid,date('Y-m-d H:i:s',time()-60)));if((int)$s->fetchColumn()>=5)throw new RuntimeException('回复过于频繁，请稍后再试。');}$now=date('Y-m-d H:i:s');$newStatus=$close?'closed':($isAdmin?'waiting_customer':'open');if($body!==null)$this->pdo->prepare('INSERT INTO ticket_messages(ticket_id,sender_type,sender_user_id,sender_admin_id,body,created_at) VALUES(?, ?, ?, ?, ?, ?)')->execute(array($id,$isAdmin?'admin':'user',$uid,$aid,$body,$now));$u=$this->pdo->prepare('UPDATE support_tickets SET status=?,version_no=version_no+1,updated_at=?,closed_at=CASE WHEN ?="closed" AND closed_at IS NULL THEN ? ELSE closed_at END WHERE id=? AND version_no=?');$u->execute(array($newStatus,$now,$newStatus,$now,$id,(int)$t['version_no']));if($u->rowCount()!==1)throw new RuntimeException('工单版本已变化，请刷新后重试。');if($isAdmin)$this->notify((int)$t['user_id'],'ticket_update',$close?'工单已关闭':'工单收到回复',$close?'你的工单已关闭。':'客服已回复你的工单。',$t['order_no'],$id,'ticket:'.$id.':version:'.((int)$t['version_no']+1).':'.($close?'close':'reply'));$result=array('id'=>$id,'status'=>$newStatus);if($isAdmin)$this->pdo->prepare('INSERT INTO admin_logs(admin_id,action,target_type,target_id,details_json,created_at) VALUES(?,?,?,?,?,?)')->execute(array($aid,$close?'close_ticket':'reply_ticket','ticket',$id,json_encode(array('status'=>$newStatus,'version_no'=>(int)$t['version_no'],'request_key'=>$key),JSON_UNESCAPED_UNICODE),$now));$this->saveOperation($id,$isAdmin?'admin':'user',$isAdmin?$aid:$uid,$close?'close':'reply',$key,$hash,$result);$this->pdo->commit();return $result;}catch(Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}}
    public function replyUser($id,$uid,$body,$key,$version=null){return $this->change($id,$uid,false,$body,$key,false,$version);}
    public function replyAdmin($id,$aid,$body,$key,$version=null){if($version===null)throw new InvalidArgumentException('版本号必填。');return $this->change($id,$aid,true,$body,$key,false,$version);}
    public function close($id,$aid,$key,$version=null){if($version===null)throw new InvalidArgumentException('版本号必填。');return $this->change($id,$aid,true,null,$key,true,$version);}
}
